import heapq

def pass_route(n: int, edges: list[list[int]], stations: list[list[int]], prices: list[int]) -> int:
    Z = len(prices)
    S = 1 << Z
    INF = float("inf")

    adj = [[] for _ in range(n)]
    for u, v, c, z in edges:
        adj[u].append((v, c, z))
        adj[v].append((u, c, z))

    station_zones = [[] for _ in range(n)]
    for s, z in stations:
        if 0 <= z < Z:
            station_zones[s].append(1 << z)

    dist = [[INF] * S for _ in range(n)]
    dist[0][0] = 0
    heap = [(0, 0, 0)]  # (cost, node, mask)

    while heap:
        d, u, mask = heapq.heappop(heap)
        if d != dist[u][mask]:
            continue
        if u == n - 1:
            return d

        # Buy any pass available at this stop.
        for bit in station_zones[u]:
            if not (mask & bit):
                nm = mask | bit
                nd = d + prices[bit.bit_length() - 1]
                if nd < dist[u][nm]:
                    dist[u][nm] = nd
                    heapq.heappush(heap, (nd, u, nm))

        # Ride each edge.
        for v, c, z in adj[u]:
            if z >= 0 and (mask >> z) & 1:
                w = 0
            else:
                w = c
            nd = d + w
            if nd < dist[v][mask]:
                dist[v][mask] = nd
                heapq.heappush(heap, (nd, v, mask))

    return min(dist[n - 1]) if min(dist[n - 1]) != INF else -1
